double h = b - a;
double fa = f(a);
double fb = f(b);
double fm = f((a + b) / 2.0);
double integral = h * fm;
double error = std::abs((h / 6.0) * (fa + 4 * fm + fb) - integral);
if (error < precision) {
    return integral;
} else {
    double left = numerical::adaptive_midpoint(f, a, (a + b) / 2.0, precision / 2.0);
    double right = numerical::adaptive_midpoint(f, (a + b) / 2.0, b, precision / 2.0);
    return left + right;
}

